# «أصول العلوم»: أصول الفقه، ومصطلح الحديث، وعلوم القرآن، ومتون العقيدة، والمذاهب الأربعة، والتزكية، والمعاملات المالية، والطب النبوي.
# دروس مبسّطة على ترتيب المتون، وكل درس يحيل إلى مواضعه في كتب المكتبة.
TR = {}
def track(k, ic, t, d): TR[k] = dict(ic=ic, t=t, d=d, lessons=[])
def les(k, id, t, idea, rules, ex, q, r=()): TR[k]['lessons'].append(dict(id=id, t=t, idea=idea, rules=rules, ex=ex, q=q, r=list(r), s=[]))

